-- 0007 survey responses and impact calculation. Generated by drizzle-kit from src/db/schema.ts, then:
--   [hand-edit 1] six composite FKs use column-scoped ON DELETE SET NULL (PostgreSQL 15+), so deleting a
--                 person or a multiplier set clears only the reference, never organization_id:
--                 event_impact_inputs_multiplier_set_same_org_fk, event_impact_inputs_updated_by_same_org_fk,
--                 impact_calculation_runs_triggered_by_same_org_fk, multiplier_sets_created_by_same_org_fk,
--                 survey_responses_entered_by_same_org_fk, survey_responses_excluded_by_same_org_fk.
--   [hand-edit 2] explicit grants (0006 model): browser roles get SELECT only, under the RLS policies above;
--                 anon gets nothing; no write privilege for any browser role.
--   [hand-edit 3] impact_calculation_runs is append-only: a trigger rejects every UPDATE, with one exception:
--                 the ON DELETE SET NULL action of impact_calculation_runs_triggered_by_same_org_fk clearing
--                 triggered_by when that person is deleted (KVKK erasure). It is recognised as a nested
--                 (foreign-key action) update that changes nothing but triggered_by → NULL; a direct UPDATE
--                 doing the same is still refused.
CREATE TYPE "public"."impact_run_status" AS ENUM('SUCCEEDED', 'INSUFFICIENT_DATA');--> statement-breakpoint
CREATE TYPE "public"."multiplier_type" AS ENUM('TYPE_I', 'TYPE_II');--> statement-breakpoint
CREATE TYPE "public"."regionalization_method" AS ENUM('NATIONAL', 'SLQ', 'CILQ', 'FLQ', 'SURVEY_BASED');--> statement-breakpoint
CREATE TYPE "public"."spend_category" AS ENUM('ACCOMMODATION', 'FOOD_BEVERAGE', 'LOCAL_TRANSPORT', 'INTERCITY_TRANSPORT', 'RETAIL_SHOPPING', 'ENTERTAINMENT_CULTURE', 'VENUE_AND_SERVICES', 'MARKETING_PRINTING', 'OTHER');--> statement-breakpoint
CREATE TYPE "public"."survey_response_channel" AS ENUM('PUBLIC_LINK', 'STAFF_ENTRY');--> statement-breakpoint
CREATE TABLE "event_impact_inputs" (
	"event_id" uuid PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"price_year" smallint NOT NULL,
	"deadweight" numeric(5, 4),
	"deadweight_source" text,
	"displacement" numeric(5, 4),
	"displacement_source" text,
	"leakage" numeric(5, 4),
	"leakage_source" text,
	"multiplier_set_id" uuid,
	"updated_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "event_impact_inputs_price_year_range" CHECK ("event_impact_inputs"."price_year" between 2000 and 2100),
	CONSTRAINT "event_impact_inputs_deadweight_sourced" CHECK (("event_impact_inputs"."deadweight" is null) = ("event_impact_inputs"."deadweight_source" is null) and ("event_impact_inputs"."deadweight" is null or ("event_impact_inputs"."deadweight" >= 0 and "event_impact_inputs"."deadweight" <= 1 and length(trim("event_impact_inputs"."deadweight_source")) >= 10))),
	CONSTRAINT "event_impact_inputs_displacement_sourced" CHECK (("event_impact_inputs"."displacement" is null) = ("event_impact_inputs"."displacement_source" is null) and ("event_impact_inputs"."displacement" is null or ("event_impact_inputs"."displacement" >= 0 and "event_impact_inputs"."displacement" <= 1 and length(trim("event_impact_inputs"."displacement_source")) >= 10))),
	CONSTRAINT "event_impact_inputs_leakage_sourced" CHECK (("event_impact_inputs"."leakage" is null) = ("event_impact_inputs"."leakage_source" is null) and ("event_impact_inputs"."leakage" is null or ("event_impact_inputs"."leakage" >= 0 and "event_impact_inputs"."leakage" <= 1 and length(trim("event_impact_inputs"."leakage_source")) >= 10)))
);
--> statement-breakpoint
ALTER TABLE "event_impact_inputs" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "impact_calculation_runs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"organization_id" uuid NOT NULL,
	"event_id" uuid NOT NULL,
	"requested_level" "impact_level" NOT NULL,
	"achieved_level" "impact_level" NOT NULL,
	"status" "impact_run_status" NOT NULL,
	"engine_version" text NOT NULL,
	"data_sufficiency" jsonb NOT NULL,
	"input_snapshot" jsonb NOT NULL,
	"multiplier_set_id" uuid,
	"attendance_basis" text,
	"attendance_used" integer,
	"sample_size" integer NOT NULL,
	"gross_direct_spend" numeric(18, 2),
	"attributable_spend" numeric(18, 2),
	"total_output_impact" numeric(18, 2),
	"total_value_added" numeric(18, 2),
	"total_income" numeric(18, 2),
	"total_employment_fte" numeric(12, 2),
	"breakdown" jsonb,
	"triggered_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "impact_calculation_runs_requested_is_a_level" CHECK ("impact_calculation_runs"."requested_level" <> 'insufficient_data'),
	CONSTRAINT "impact_calculation_runs_achieved_not_above_requested" CHECK (array_position(array['insufficient_data', 'spend', 'attributable_spend', 'economic_impact']::impact_level[], "impact_calculation_runs"."achieved_level") <= array_position(array['insufficient_data', 'spend', 'attributable_spend', 'economic_impact']::impact_level[], "impact_calculation_runs"."requested_level")),
	CONSTRAINT "impact_calculation_runs_status_matches_level" CHECK (("impact_calculation_runs"."status" = 'SUCCEEDED') = ("impact_calculation_runs"."achieved_level" = "impact_calculation_runs"."requested_level")),
	CONSTRAINT "impact_calculation_runs_gross_only_when_reached" CHECK (("impact_calculation_runs"."gross_direct_spend" is not null) = (array_position(array['insufficient_data', 'spend', 'attributable_spend', 'economic_impact']::impact_level[], "impact_calculation_runs"."achieved_level") >= 2)),
	CONSTRAINT "impact_calculation_runs_attributable_only_when_reached" CHECK (("impact_calculation_runs"."attributable_spend" is not null) = (array_position(array['insufficient_data', 'spend', 'attributable_spend', 'economic_impact']::impact_level[], "impact_calculation_runs"."achieved_level") >= 3)),
	CONSTRAINT "impact_calculation_runs_economic_only_when_reached" CHECK (case when "impact_calculation_runs"."achieved_level" = 'economic_impact'
        then "impact_calculation_runs"."total_output_impact" is not null and "impact_calculation_runs"."total_value_added" is not null and "impact_calculation_runs"."total_income" is not null and "impact_calculation_runs"."total_employment_fte" is not null
        else "impact_calculation_runs"."total_output_impact" is null and "impact_calculation_runs"."total_value_added" is null and "impact_calculation_runs"."total_income" is null and "impact_calculation_runs"."total_employment_fte" is null end),
	CONSTRAINT "impact_calculation_runs_economic_needs_multiplier_set" CHECK ("impact_calculation_runs"."achieved_level" <> 'economic_impact' or "impact_calculation_runs"."multiplier_set_id" is not null),
	CONSTRAINT "impact_calculation_runs_reached_needs_attendance" CHECK ("impact_calculation_runs"."achieved_level" = 'insufficient_data' or ("impact_calculation_runs"."attendance_used" is not null and "impact_calculation_runs"."attendance_used" > 0 and "impact_calculation_runs"."attendance_basis" in ('CHECKIN', 'REGISTRATION', 'ORGANIZER_ESTIMATE'))),
	CONSTRAINT "impact_calculation_runs_figures_non_negative" CHECK (coalesce("impact_calculation_runs"."gross_direct_spend", 0) >= 0 and coalesce("impact_calculation_runs"."attributable_spend", 0) >= 0 and coalesce("impact_calculation_runs"."total_output_impact", 0) >= 0
        and coalesce("impact_calculation_runs"."total_value_added", 0) >= 0 and coalesce("impact_calculation_runs"."total_income", 0) >= 0 and coalesce("impact_calculation_runs"."total_employment_fte", 0) >= 0),
	CONSTRAINT "impact_calculation_runs_sample_size_non_negative" CHECK ("impact_calculation_runs"."sample_size" >= 0),
	CONSTRAINT "impact_calculation_runs_snapshot_is_object" CHECK (jsonb_typeof("impact_calculation_runs"."input_snapshot") = 'object'),
	CONSTRAINT "impact_calculation_runs_sufficiency_is_array" CHECK (jsonb_typeof("impact_calculation_runs"."data_sufficiency") = 'array')
);
--> statement-breakpoint
ALTER TABLE "impact_calculation_runs" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
