CREATE FUNCTION app.impact_calculation_runs_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF pg_trigger_depth() > 1 AND OLD.triggered_by IS NOT NULL AND NEW.triggered_by IS NULL
     AND (to_jsonb(NEW) - 'triggered_by') = (to_jsonb(OLD) - 'triggered_by') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'impact_calculation_runs rows are immutable; store a new run instead' USING ERRCODE = 'restrict_violation';
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app.impact_calculation_runs_immutable() FROM PUBLIC;--> statement-breakpoint
CREATE TRIGGER "impact_calculation_runs_no_update" BEFORE UPDATE ON "impact_calculation_runs" FOR EACH ROW EXECUTE FUNCTION app.impact_calculation_runs_immutable();
